        vm.assume(value > 0);
        vm.assume(sender != address(0));
        vm.deal(sender, value);
        vm.prank(sender);
        bool ok;
        try c.deposit{value: value}() { ok = true; } catch { ok = false; }
        assertTrue(ok);
